import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused Matmul + Dropout + Softmax kernel
fused_kernel_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <math.h>
#include <stdio.h>

#define TILE_SIZE 32
#define BLOCK_ROWS 8
#define BLOCK_COLS 32

__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float* __restrict__ reduction_buffer,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    unsigned long long seed,
    bool training
) {
    // Shared memory for tiles
    __shared__ float x_tile[TILE_SIZE][TILE_SIZE];
    __shared__ float w_tile[TILE_SIZE][TILE_SIZE];

    // Each thread block computes one element in the output
    int out_row = blockIdx.y;
    int out_col = blockIdx.x * blockDim.x + threadIdx.x;

    if (out_row >= batch_size || out_col >= out_features) return;

    float sum = 0.0f;

    // Loop over input features in tiles
    for (int tile_idx = 0; tile_idx < (in_features + TILE_SIZE - 1) / TILE_SIZE; ++tile_idx) {
        // Load x tile
        int x_col = tile_idx * TILE_SIZE + threadIdx.x;
        if (x_col < in_features) {
            x_tile[threadIdx.y][threadIdx.x] = x[out_row * in_features + x_col];
        } else {
            x_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load w tile
        int w_row = tile_idx * TILE_SIZE + threadIdx.y;
        int w_col = out_col;
        if (w_row < in_features) {
            w_tile[threadIdx.y][threadIdx.x] = weight[w_row * out_features + w_col];
        } else {
            w_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += x_tile[threadIdx.y][k] * w_tile[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Add bias
    if (bias != nullptr) {
        sum += bias[out_col];
    }

    // Apply dropout and store
    if (training) {
        // Philox-inspired PRNG
        unsigned long long subsequence = (unsigned long long)out_row * out_features + out_col;
        unsigned long long counter = subsequence * 0x5851f42d4c957f2dULL + seed;
        counter ^= (counter >> 21);
        counter *= 0x9fb21c651e98dfc5ULL;
        counter ^= counter >> 33;
        float rand_val = (float)(counter & 0xFFFFFF) / (float)0xFFFFFF;

        if (rand_val < dropout_p) {
            sum = 0.0f;
        } else {
            sum = sum / (1.0f - dropout_p);
        }
    }

    // Store intermediate result and compute max per row
    __shared__ float row_max[32];
    int tid = threadIdx.x;

    // First, find max for this row
    row_max[tid] = sum;

    // Reduction to find global max for the row
    for (int stride = 16; stride > 0; stride >>= 1) {
        __syncthreads();
        if (tid + stride < blockDim.x && out_col + stride < out_features) {
            // We need to peek at neighboring element - store in smem first
            // For now, just use what we have
        }
    }

    // Store for softmax pass
    output[out_row * out_features + out_col] = sum;
}

__global__ void softmax_kernel(
    float* __restrict__ x,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int tid = threadIdx.x;
    int warpid = threadIdx.x / 64;
    int lane = tid % 64;

    __shared__ float s_data[32];

    // Load value
    float val = x[row * out_features + col];

    // Find max using warp shuffle
    float max_val = val;
    #pragma unroll
    for (int i = 32; i > 0; i /= 2) {
        float other = __shfl_down(max_val, i, 64);
        max_val = fmaxf(max_val, other);
    }

    // Get max across warps in block
    if (lane == 0) {
        s_data[warpid % 32] = max_val;
    }
    __syncthreads();

    max_val = s_data[lane % 32];
    #pragma unroll
    for (int i = 16; i > 0; i /= 2) {
        float other = __shfl_down(max_val, i, 32);
        max_val = fmaxf(max_val, other);
    }
    max_val = __shfl(max_val, 0, 64);

    // Find sum of exp
    val = expf(val - max_val);
    float sum_exp = val;
    #pragma unroll
    for (int i = 32; i > 0; i /= 2) {
        float other = __shfl_down(sum_exp, i, 64);
        sum_exp += other;
    }

    if (lane == 0) {
        s_data[warpid % 32] = sum_exp;
    }
    __syncthreads();

    sum_exp = s_data[lane % 32];
    #pragma unroll
    for (int i = 16; i > 0; i /= 2) {
        float other = __shfl_down(sum_exp, i, 32);
        sum_exp += other;
    }
    sum_exp = __shfl(sum_exp, 0, 64);

    // Final softmax
    x[row * out_features + col] = val / sum_exp;
}

torch::Tensor fused_matmul_dropout_softmax_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float dropout_p,
    bool training
) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(1);

    auto output = torch::zeros({batch_size, out_features}, x.options());

    // Use a tiled approach
    dim3 blockDim(32, 32);  // 32x32 threads per block
    dim3 gridDim((out_features + 31) / 32, (batch_size + 31) / 32);

    unsigned long long seed = (unsigned long long)(x.data_ptr<float>() + time(NULL));

    // Check for valid sizes
    if (batch_size > 0 && in_features > 0 && out_features > 0) {
        // Adjust grid for row-major processing
        dim3 blockDimX(256);
        dim3 gridDimX((out_features + 255) / 256, batch_size);

        fused_matmul_dropout_softmax_kernel<<<gridDimX, blockDimX>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.defined() ? bias.data_ptr<float>() : nullptr,
            output.data_ptr<float>(),
            nullptr,
            batch_size,
            in_features,
            out_features,
            dropout_p,
            seed,
            training
        );

        hipError_t err = hipGetLastError();
        if (err != hipSuccess) {
            // Try fallback with smaller blocks
            dim3 blockDim2(128);
            dim3 gridDim2((out_features + 127) / 128, batch_size);
            fused_matmul_dropout_softmax_kernel<<<gridDim2, blockDim2>>>(
                x.data_ptr<float>(),
                weight.data_ptr<float>(),
                bias.defined() ? bias.data_ptr<float>() : nullptr,
                output.data_ptr<float>(),
                nullptr,
                batch_size,
                in_features,
                out_features,
                dropout_p,
                seed,
                training
            );
        }
    }

    // Apply softmax
    int blockSize = 256;
    int gridSize = (out_features + blockSize - 1) / blockSize;
    softmax_kernel<<<dim3(gridSize, batch_size), dim3(blockSize, 1)>>>(
        output.data_ptr<float>(),
        batch_size,
        out_features
    );

    return output;
}
"""

