    float max_val = s_max[0];
    __syncthreads();

    // Compute sum of exp
    val = expf(fmaxf(val - max_val, -50.0f));  // Stable softmax
    x[idx] = val;

    s_sum[tid] = val;
    __syncthreads();

    for (int stride = blockDim.x * blockDim.y / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] = s_sum[tid] + s_sum[tid + stride];
        }
        __syncthreads();
    }

    float sum_exp = s_sum[0];
    __syncthreads();

