#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    float scale,
    bool training
) {
    int out_row = blockIdx.y * blockDim.y + threadIdx.y;
    int out_col = blockIdx.x * blockDim.x + threadIdx.x;

    if (out_row >= batch_size || out_col >= out_features) return;

    // Compute matmul: output[row, col] = sum(x[row, k] * weight[col, k])
    float sum = 0.0f;

    for (int k = 0; k < in_features; ++k) {
        sum += x[out_row * in_features + k] * weight[out_col * in_features + k];
    }

    // Add bias
    if (bias != nullptr) {
        sum += bias[out_col];
    }

    // Apply dropout (only during training)
    if (training) {
        unsigned int idx = (unsigned int)(out_row * out_features + out_col);
        unsigned int hash = idx * 0x9e3779b9;
        hash ^= hash >> 16;
        hash *= 0x85ebca6b;
        hash ^= hash >> 13;
        hash *= 0xc2b2ae35;
        hash ^= hash >> 16;
        float rand_val = (float)(hash & 0xFFFFFF) / (float)0x1000000;

        if (rand_val < dropout_p) {
            sum = 0.0f;
        } else {
            sum = sum * scale;
        }
    }

    output[out_row * out_features + out_col] = sum;
}

// softmax_find_max: find max value in each row
__global__ void softmax_find_max_kernel(
    const float* __restrict__ input,
    float* __restrict__ row_max,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float val = input[idx];

    // Use atomic max to find global maximum for this row
    atomicMax(&row_max[row], val);
}

// softmax_sum_exp: compute sum of exp(max_offset) for each row
__global__ void softmax_sum_exp_kernel(
    float* __restrict__ input,
    const float* __restrict__ row_max,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float max_val = row_max[row];
    float exp_val = expf(fmaxf(input[idx] - max_val, -50.0f));
    input[idx] = exp_val;

    // Accumulate to sum using atomic add
    atomicAdd(&row_max[row], exp_val);  // Reuse row_max storage for sum
}

// softmax_normalize: divide by sum
__global__ void softmax_normalize_kernel(
    float* __restrict__ input,
    const float* __restrict__ row_sum,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float sum = row_sum[row];
    input[idx] = input[idx] / fmaxf(sum, 1e-10f);
