        // Find max using warp shuffle with atomic for global max
        auto max_temp = torch::full({1}, -1e30f, x.options());
        atomicMax_kernel<<<softGrid, softBlock>>>(output.data_ptr<float>(), max_temp.data_ptr<float>(), batch_size, out_features);

        // Sum exp - this needs global atomics
        // We'll do a two-pass approach
    } else {
        softmax_row_wise_kernel<<<gridSize, blockSize>>>(output.data_ptr<float>(), batch_size, out_features);
