        unsigned int hash = idx * 0x9e3779b9;
        hash ^= hash >> 16;
        hash *= 0x85ebca6b;
        hash ^= hash >> 13;
        hash *= 0xc2b2ae35;
        hash ^= hash >> 16;
        float rand_val = (float)(hash & 0xFFFFFF) / (float)0x1000000;

        if (rand_val < dropout_p) {
            sum = 0.0f;
        } else {
            sum = sum * scale;  // scale = 1.0 / (1.0 - dropout_p)
        }
    }

    output[out_row * out_features + out_col] = sum;
}

__global__ void softmax_kernel(
    float* __restrict__ x,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

