# Optimized Fused Matmul + Dropout + Softmax with tiling
fused_kernel_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <math.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 16

__global__ void matmul_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    float scale,
    bool training,
    unsigned long long seed
) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Compute output position
    int row_m = by * TILE_M + ty;
    int col_n = bx * TILE_N + tx;

    if (row_m >= batch_size || col_n >= out_features) return;

    // Shared memory for tiles
    __shared__ float x_tile[TILE_M][TILE_K];
    __shared__ float w_tile[TILE_K][TILE_N];

    float sum = 0.0f;

    // Loop over tiles
    int num_tiles = (in_features + TILE_K - 1) / TILE_K;

    for (int t = 0; t < num_tiles; ++t) {
        // Load x tile (batch_size, in_features)
        int k = t * TILE_K + tx;
        if (k < in_features) {
            x_tile[ty][tx] = x[row_m * in_features + k];
        } else {
            x_tile[ty][tx] = 0.0f;
        }

        // Load w tile (in_features, out_features) - transpose for better memory access
        int k_w = t * TILE_K + ty;
        if (k_w < in_features && col_n < out_features) {
            w_tile[ty][tx] = weight[col_n * in_features + k_w];
        } else {
            w_tile[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        for (int k = 0; k < TILE_K; ++k) {
            sum += x_tile[ty][k] * w_tile[k][tx];
        }

        __syncthreads();
    }

    // Add bias
    if (bias != nullptr) {
        sum += bias[col_n];
    }

    // Apply dropout
    if (training) {
        unsigned long long idx = (unsigned long long)row_m * out_features + col_n;
        unsigned long long hash = idx ^ seed;
        hash = hash * 0x9e3779b97f4a7c15ULL;
        hash = (hash ^ (hash >> 30)) * 0xbf58476d1ce4e5b9ULL;
        hash = (hash ^ (hash >> 27)) * 0x94d049bb133111ebULL;
        hash = hash ^ (hash >> 31);
        float rand_val = (float)(hash & 0xFFFFFF) / (float)0x1000000;

        if (rand_val < dropout_p) {
            sum = 0.0f;
        } else {
            sum *= scale;
        }
    }

    if (row_m < batch_size && col_n < out_features) {
        output[row_m * out_features + col_n] = sum;
    }
}

__global__ void softmax_row_wise_kernel(
    float* __restrict__ x,
    int batch_size,
    int out_features
) {
    int row = blockIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= out_features) return;

    int idx = row * out_features + col;
    float val = x[idx];

    // Shared memory for reduction
    __shared__ float s_data[1024];
    int tid = threadIdx.x;
    int row_idx = row;

    // Find max using warp primitives
    float max_val = val;

    // First reduce within warp
    #pragma unroll
    for (int i = 16; i > 0; i /= 2) {
        float other = __shfl_down(max_val, i, 32);
        max_val = fmaxf(max_val, other);
    }

    // Warp leaders store to shared memory
    int wid = tid / 32;
    int lane = tid % 32;
    if (lane == 0) {
        s_data[wid] = max_val;
    }

    __syncthreads();

    // Reduce across warps
    if (tid < 32) {
        max_val = s_data[tid];
        #pragma unroll
        for (int i = 16; i > 0; i /= 2) {
            float other = __shfl_down(max_val, i, 32);
            max_val = fmaxf(max_val, other);
        }
        if (tid == 0) {
            s_data[0] = max_val;
        }
    }

    __syncthreads();
    max_val = s_data[0];

    // Compute exp
    val = expf(fmaxf(val - max_val, -50.0f));
    x[idx] = val;

    // Find sum
    float sum_exp = val;

    // Reduce within warp
    #pragma unroll
    for (int i = 16; i > 0; i /= 2) {
        float other = __shfl_down(sum_exp, i, 32);
        sum_exp += other;
    }

    if (lane == 0) {
        s_data[wid] = sum_exp;
    }

    __syncthreads();

    if (tid < 32) {
        sum_exp = s_data[tid];
        #pragma unroll
        for (int i = 16; i > 0; i /= 2) {
            float other = __shfl_down(sum_exp, i, 32);
            sum_exp += other;
        }
        if (tid == 0) {
            s_data[0] = sum_exp;
        }
    }

    __syncthreads();
    sum_exp = s_data[0];

    // Normalize
    x[idx] = val / fmaxf(sum_exp, 1e-10f);
}

torch::Tensor fused_matmul_dropout_softmax_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    float dropout_p,
    bool training
) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, x.options());
    float scale = 1.0f / (1.0f - dropout_p + 1e-6f);
    unsigned long long seed = (unsigned long long)(x.data_ptr<float>() + (unsigned long long)(x.data_ptr<float>()) >> 13);

    // Matmul with tiling
    dim3 blockDim(TILE_N, TILE_M);  // 32x32 threads
    dim3 gridDim((out_features + TILE_N - 1) / TILE_N, (batch_size + TILE_M - 1) / TILE_M);

    matmul_kernel<<<gridDim, blockDim>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        dropout_p,
        scale,
        training,
        seed
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        // Wait and check
        hipDeviceSynchronize();
    }

    // Softmax with block size 256 for out_features
    int soft_threads = 256;
    int soft_blocks = (out_features + soft_threads - 1) / soft_threads;

    dim3 blockSize(soft_threads);
    dim3 gridSize(soft_blocks, batch_size);

    // Only process valid columns
    auto temp = output.clone();

    // For very large out_features, we need to handle reduction properly
    // Use atomics as fallback for large sizes
    if (out_features > 1024) {
        // Use global memory atomics approach
        auto row_max = torch::full({batch_size}, -1e30f, x.options());
        auto row_sum = torch::zeros({batch_size}, x.options());

        dim3 softBlock(256);
        dim3 softGrid((out_features + 255) / 256, batch_size);

        // Find max using warp shuffle with atomic for global max
        auto max_temp = torch::full({1}, -1e30f, x.options());
        atomicMax_kernel<<<softGrid, softBlock>>>(output.data_ptr<float>(), max_temp.data_ptr<float>(), batch_size, out_features);

        // Sum exp - this needs global atomics
        // We'll do a two-pass approach
    } else {
        softmax_row_wise_kernel<<<gridSize, blockSize>>>(output.data_ptr<float>(), batch_size, out_features);
    }

    return output;
}
